<?php
declare(strict_types=1);
require __DIR__ . '/includes/lib.php';
$user=require_login();$pdo=db();$hour=(int)date('G');$greet=$hour<12?'Good morning':($hour<18?'Good afternoon':'Good evening');$first=$user['level']==='admin'?($user['display_name']?:'Administrator'):($user['first_name']?:'Student');
page_start('Dashboard','dashboard'); ?>
<div class="head"><div><h1><?=e($greet)?>, <?=e($first)?></h1><p class="muted lead-sm"><?php if($user['level']==='admin'): ?>University-wide WMSU Student Council Funds overview.<?php elseif($user['level']==='mayor'): ?>College Mayor workspace for <?=e($user['college'])?>.<?php elseif($user['level']==='officer'): ?>Officer workspace for <?=e($user['college']??'your college')?>.<?php else: ?>Your student account, annual fees, and council announcements.<?php endif;?></p></div></div>
<?php if($user['level']==='student'): ?>
<?php $st=$pdo->prepare('SELECT school_year,program,college,year_level FROM student WHERE student_id=?');$st->execute([$user['student_id']]);$student=$st->fetch();$en=$pdo->prepare('SELECT e.school_year,e.program_name_snapshot program,e.year_level,c.college_name college FROM student_enrollment e JOIN college c ON c.college_id=e.college_id WHERE e.student_id=? ORDER BY e.school_year DESC,e.enrollment_id DESC LIMIT 1');$en->execute([$user['student_id']]);$snapshot=$en->fetch();if($snapshot)$student=array_merge($student,$snapshot);$st=$pdo->prepare('SELECT pr.fee_name,sp.amount_due,sp.status,sp.school_year,sp.college_share,sp.university_share FROM student_payment sp JOIN payment_requirement pr ON pr.requirement_id=sp.requirement_id WHERE sp.student_id=? ORDER BY sp.school_year DESC,pr.fee_name');$st->execute([$user['student_id']]);$payments=$st->fetchAll();$st=$pdo->prepare("SELECT title,body,announcement_type,publish_at,event_date,deadline FROM announcement WHERE status='Published' AND (college_id IS NULL OR college_id=(SELECT college_id FROM college WHERE college_name=?)) ORDER BY publish_at DESC LIMIT 8");$st->execute([$student['college']]);$news=$st->fetchAll(); ?>
<div class="two"><section class="card"><h2>Enrollment information</h2><dl class="detail"><dt>College</dt><dd><?=e($student['college'])?></dd><dt>Program</dt><dd><?=e($student['program'])?></dd><dt>Year level</dt><dd>Year <?= (int)$student['year_level']?></dd><dt>School year enrolled</dt><dd><?=e($student['school_year']??'Not set')?></dd></dl></section><section class="card"><h2>Annual fees</h2><p class="muted">Insurance ₱70 + CSC ₱200 = ₱270.</p><div class="tablewrap"><table><thead><tr><th>Fee</th><th>School year</th><th>Amount</th><th>Status</th></tr></thead><tbody><?php foreach($payments as $p): ?><tr><td><?=e($p['fee_name'])?></td><td><?=e($p['school_year'])?></td><td><?=money($p['amount_due'])?></td><td><?=e($p['status'])?></td></tr><?php endforeach;?><?php if(!$payments): ?><tr><td colspan="4" class="empty">No fee records yet. Open My payments to check available fees.</td></tr><?php endif;?></tbody></table></div><p><a href="payments.php">Open payment history and upload proof</a></p></section></div>
<section class="card"><h2>Latest announcements</h2><?php foreach($news as $n): ?><article><span class="pill"><?=e($n['announcement_type'])?></span><strong> <?=e($n['title'])?></strong><p><?=nl2br(e($n['body']))?></p><small class="muted">Published <?=e($n['publish_at'])?> <?= $n['event_date']?'· Event '.e($n['event_date']):'' ?></small></article><hr><?php endforeach;?><?php if(!$news): ?><p class="muted">No announcements published yet.</p><?php endif;?><a href="announcements.php">View all announcements</a></section>
<?php else: ?>
<?php $cid=(int)($user['college_id']??0);$where=$user['level']==='admin'?'':' WHERE college_id=?';$st=$pdo->prepare("SELECT status,COUNT(*) n,COALESCE(SUM(amount_requested),0) amount FROM fund_request".($where?' WHERE college_id=?':'')." GROUP BY status");$st->execute($user['level']==='admin'?[]:[$cid]);$req=[];foreach($st->fetchAll() as $r)$req[$r['status']]=$r;
$st=$pdo->prepare("SELECT COUNT(*) FROM student_payment WHERE status IN ('Proof Submitted','Under Verification')".($user['level']==='admin'?'':' AND college_id=?'));$st->execute($user['level']==='admin'?[]:[$cid]);$waiting=(int)$st->fetchColumn();
$st=$pdo->prepare("SELECT COUNT(*) FROM student".($user['level']==='admin'?'':' WHERE college=?'));$st->execute($user['level']==='admin'?[]:[$user['college']]);$students=(int)$st->fetchColumn();
?>
<section class="cards"><div class="stat"><span>Students</span><strong><?=number_format($students)?></strong></div><div class="stat"><span>Requests pending</span><strong><?=(int)($req['Pending']['n']??0)?></strong></div><div class="stat"><span>Payments needing review</span><strong><?=$waiting?></strong></div></section>
<div class="two"><section class="card"><h2>Quick actions</h2><ul class="plain"><li><a href="requests.php">Review or submit requests</a></li><li><a href="payments.php">Verify student payment proofs</a></li><li><a href="announcements.php">Publish announcements</a></li><?php if(in_array($user['level'],['admin','mayor'],true)): ?><li><a href="college_ledger.php">View financial history</a></li><li><a href="members.php">Manage members</a></li><?php endif;?><?php if($user['level']==='admin'): ?><li><a href="mayors.php">Assign College Mayors</a></li><li><a href="enrollments.php">Manage school-year enrollments</a></li><li><a href="catalog.php">Manage colleges and programs</a></li><li><a href="university_ledger.php">Manage university central fund</a></li><?php endif;?></ul></section><section class="card"><h2>Access scope</h2><?php if($user['level']==='admin'): ?><p>You have university-wide access across all colleges. You can assign and reassign College Mayors.</p><?php elseif($user['level']==='mayor'): ?><p>You can manage council activity for <strong><?=e($user['college'])?></strong>. Officer assignments and request approvals are limited to this college.</p><?php else: ?><p>You can verify payments, publish announcements, view your college requests, and submit proposals for Mayor approval. You cannot allocate funds directly.</p><?php endif;?></section></div>
<?php endif;?>
<?php page_end(); ?>
